/* ================= TAVA LABS — FOREST LUXE OVERRIDES ================= */
:root{--forest:#000000;--forest-deep:#000000;--champagne:#D8C19A;--gold-deep:#B78B45;--gold:#C19A3D;--ivory:#FFFFFF}
html,body{overflow-x:hidden!important}
body{background:#FFFFFF!important}
/* hero: full-bleed bottle-over-cream-silk photo */
.hero__wrapper{background-image:none!important;background-color:#FFFFFF!important;overflow:hidden}
.logo__image__hero{top:0!important;bottom:0!important;width:100%;height:100%;object-fit:cover}
.hero__content__wrapper{position:relative;z-index:2}
.hero__content__wrapper .heading__two{color:#000000!important}
/* statement: deep-forest band with curved top edge + tilted TAVA LABS */
.who{position:relative;margin-top:0;border-top-left-radius:0;border-top-right-radius:0;background:#FFFFFF!important;padding-top:150px;overflow:hidden}/* FLIPPED curve: ivory scoop dips DOWN into the forest band in the centre (opposite of the previous forest hill that rose up) */.who::before{content:"";position:absolute;top:0;left:-10%;width:120%;height:110px;background:#FFFFFF;border-bottom-left-radius:50% 100%;border-bottom-right-radius:50% 100%;z-index:1}.who__wrapper{position:relative;z-index:2}
.tava-hero-band{position:absolute;top:6px;left:0;width:100%;text-align:center;transform:rotate(-4deg);z-index:5;pointer-events:none}
.tava-hero-band span{font-family:Kanit,sans-serif;font-weight:900;font-size:clamp(54px,13vw,168px);line-height:1;color:#D8C19A;text-transform:uppercase;white-space:nowrap}
.who .heading__one{color:#000000!important}
.who .paragraph{color:#000000!important}
.content__right{position:relative}
.image-9{width:100%;height:100%;object-fit:cover;border-radius:50%}
.tava-curve{position:absolute;inset:-7%;width:114%;height:114%;animation:tava-spin 40s linear infinite;pointer-events:none}
.tava-curve text{fill:#D8C19A;font-family:Kanit,sans-serif;font-size:12.5px;font-weight:700;letter-spacing:3.5px;text-transform:uppercase}
@keyframes tava-spin{to{transform:rotate(360deg)}}
/* products */
.products{background:#FFFFFF!important}
.product__box{background:#FFFFFF!important;border-color:#000000!important}
.new__sticker{background:#000000!important}
.new__text{color:#D8C19A!important}
.solds__out__marquee{border-color:#000000!important}
.marquee-link{color:#000000!important}
.button_one.is--products{background:#000000!important;color:#D8C19A!important}
.button_one.is--products-all{background:#000000!important;color:#D8C19A!important}
/* values / benefits */
.benefits.is--desktop,.benefits.is--mobile{background:#FFFFFF!important}
.benefits .heading__one{color:#000000!important}
.tava-lede{font-family:'Futura book font',sans-serif;font-size:20px;color:#000000;text-align:center;margin-top:12px}
.feature__paragraph{color:#000000!important}
.feature__image{border-radius:50%}
/* subscribe */
.subscribe__product{background:#FFFFFF!important}
.heading__one__stroke{-webkit-text-stroke:1.5px #000000!important;color:transparent!important}
.subscribe__background__image{background-image:none!important}
.cream__image{mix-blend-mode:multiply}
/* founder */
.founder{background:linear-gradient(180deg,#FFFFFF,#D8C19A)!important}
.founder .heading__one{color:#000000!important}
#kjFilm{width:100%;height:100%;object-fit:cover;border-radius:50%;background:#000}
/* footer */
.footer,.footer__desktop,.footer__mobile{background:#000000!important}
.footer__link{color:#FFFFFF!important}
.footer__link__title{color:#D8C19A!important}
.footer__link__title a{color:inherit;text-decoration:none}
.footer__box__wrapper{border-color:#B78B45!important;background:#FFFFFF}
.paragraph-2{color:#000000!important}
.footer-submit-button{background:#000000!important;color:#D8C19A!important}
.tava-fineprint,.tava-copy{color:#D8C19A;text-align:center;font-family:'Futura book font',sans-serif;font-size:14px;text-transform:none;max-width:820px;margin:26px auto 0;padding:0 20px;line-height:1.6}
.tava-fineprint a{color:#FFFFFF}
.tava-copy{margin-top:10px;font-size:13px;letter-spacing:.06em}
.logo__background img{max-width:620px;margin:0 auto;display:block}
/* === NO BLUE / NO YELLOW — every remaining Webflow surface === */
.body,body{background:#FFFFFF!important}
.nav__dropdown__list,.nav__dropdown__list__wrap{background:#000000!important;background-image:none!important}
.nav__dropdown__list__wrap .nav__product__title,.nav__dropdown__list__wrap .nav__product__description{color:#FFFFFF!important}
.button-3{background:#000000!important;color:#FFFFFF!important}
.accordion__item__wrapper.tabs__accordion,.accordion__item.tabs__accordion{background:#000000!important;background-image:none!important}
.mobile__nav__product__name,.mobile__nav__product__description{color:#FFFFFF!important}
.hero__wrapper{background-color:#FFFFFF!important;background-image:none!important}
.benefits,.benefits.is--desktop,.benefits.is--mobile{background:#FFFFFF!important;background-image:none!important}
.top__heading__wrapper,.top__heading__wrapper.is--subscribe{background:#FFFFFF!important;background-image:none!important}
.subscribe__product,.subscribe__product.is--mobile,.subscribe__product.is-desktop{background:#FFFFFF!important;background-image:none!important}
.founder{background:linear-gradient(180deg,#FFFFFF,#D8C19A)!important;background-image:linear-gradient(180deg,#FFFFFF,#D8C19A)!important}
.reviews{background:#D8C19A!important;background-image:none!important}
.review__slide{background:#000000!important}
.footer__desktop,.footer__desktop.is--desktop,.footer__mobile,.footer__mobile.is--mobile{background:#000000!important;background-image:none!important}
.w-button{background-color:#000000}
mark{background:#000000;color:#FFFFFF}

.footer__logo__mobile{max-width:420px;margin:26px auto 0;display:block}
/* scrolled header: Forest, never yellow — Webflow IX2 sets this inline, remapped in tava-webflow.js; this guards the border/underline */
.nav__wrappper.desktop,.nav__wrappper.mobile-tablet{border-color:#000000!important}

/* TAVA GREEN COMPONENTS: forest green replaces black on shared components */
:root{--forest:#123B2C;--forest-deep:#08251D}
.header{background:#08251D!important}
.new__sticker{background:#08251D!important}
.button_one.is--products,.button_one.is--products-all{background:#08251D!important}
.footer,.footer__desktop,.footer__desktop.is--desktop,.footer__mobile,.footer__mobile.is--mobile{background:#08251D!important;background-image:none!important}
.footer-submit-button{background:#08251D!important}
.nav__dropdown__list,.nav__dropdown__list__wrap{background:#08251D!important;background-image:none!important}
.button-3{background:#08251D!important}
.accordion__item__wrapper.tabs__accordion,.accordion__item.tabs__accordion{background:#08251D!important;background-image:none!important}
.review__slide{background:#08251D!important}
.w-button{background-color:#08251D!important}
mark{background:#08251D!important}
.product__box{border-color:#123B2C!important}
.solds__out__marquee{border-color:#123B2C!important}
.nav__wrappper.desktop,.nav__wrappper.mobile-tablet{border-color:#123B2C!important}

/* menu links: anchors styled like the divs they replace */
a.accordion__trigger{display:block;text-decoration:none;color:inherit;cursor:pointer}
a.accordion__item{display:block;text-decoration:none;color:inherit;cursor:pointer}
a.nav__product__content__wrapper{display:block;text-decoration:none;color:inherit;cursor:pointer}
